        """

        if not state_dict:
            return

        if len(state_dict.get("dataset", [])) != len(self._datasets):
            raise RuntimeError("The number of datasets in the state_dict does not match the current object's datasets.")

        for dataset_idx, dataset in enumerate(self._datasets):
            if str(dataset_idx) not in state_dict.get("dataset", {}):
                raise RuntimeError(f"Missing dataset index {dataset_idx} in the state_dict.")

            dataset.load_state_dict(state_dict["dataset"][str(dataset_idx)])
