from itertools import chain


class Node:
    def __init__(self, modules: List[Module]):
        self.modules = modules


class Module:
    def __init__(self, module_params: List[ModuleParam]):
        self.module_params = module_params


class ModuleParam:
    def __init__(self, key: str, value: Union[str, int]):
        self.key = key
        self.value = value


def extract_values(node: Node, key: str) -> List[str]:
    extracted_values = [param.value for module in node.modules for param in module.module_params if param.key == key]
    return extracted_values


def extract_values_from_nodes(nodes: List[Node], key: str) -> List[str]:
    extracted_values = list(map(lambda node: extract_values(node, key), nodes))
    flattened_values = list(chain.from_iterable(extracted_values))
    unique_values = list(set(flattened_values))
    return unique_values


