            field, boost_str = field.split(":")
            boost = float(boost_str)
        field_boosts[field] = boost
    return field_boosts

def ensure_list(input_value: Any, default_value: List[str]) -> List[str]:
    if input_value is None:
        return default_value
    elif isinstance(input_value, list):
        return input_value
    else:
        return [input_value]

